package nl.voetbalhub.app;
import android.app.Activity;
import android.graphics.*;
import android.graphics.drawable.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
/** Published, fresh originals only. Rotation stops off screen and with reduced motion. */
public final class HomeSlideshow40 extends FrameLayout implements FeedRepository.Listener {
 private final Activity a;private final HomeFeatureView.OpenArticle open;private final Runnable fallback;private final ImageView image;private final TextView category,title,intro;private TextView dots;private final ArrayList<JSONObject> slides=new ArrayList<>();private int index;private boolean attached;private float downX,downY;
 private int dp(float n){return PremiumDesign40.dp(a,n);}
 private final Runnable rotate=new Runnable(){public void run(){if(attached&&getWindowVisibility()==VISIBLE&&hasWindowFocus()&&PremiumDesign40.motion(a)&&slides.size()>1){index=(index+1)%slides.size();render();}if(attached)postDelayed(this,7000);}};
 public HomeSlideshow40(Activity activity,HomeFeatureView.OpenArticle action,Runnable empty){super(activity);a=activity;open=action;fallback=empty;PremiumDesign40.card(this,PremiumDesign40.EDGE);PremiumDesign40.touch(this);
  image=new ImageView(a);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setImportantForAccessibility(2);addView(image,new LayoutParams(-1,-1));View shade=new View(a);shade.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0x22020805,0xB3020805,0xFC020805}));addView(shade,new LayoutParams(-1,-1));
  LinearLayout copy=new LinearLayout(a);copy.setOrientation(1);copy.setPadding(dp(18),dp(17),dp(18),dp(38));category=PremiumDesign40.text(a,"VELDIO ORIGINALS",10,PremiumDesign40.GREEN,true);copy.addView(category);title=PremiumDesign40.text(a,"",25,PremiumDesign40.WHITE,true);title.setMaxLines(3);title.setEllipsize(android.text.TextUtils.TruncateAt.END);title.setPadding(0,dp(10),0,dp(8));copy.addView(title);intro=PremiumDesign40.text(a,"",12,0xFFDBE8DF,false);intro.setMaxLines(2);intro.setEllipsize(android.text.TextUtils.TruncateAt.END);copy.addView(intro);addView(copy,new LayoutParams(-1,-2,Gravity.BOTTOM));
  LinearLayout controls=new LinearLayout(a);controls.setGravity(Gravity.CENTER);for(int n:new int[]{-1,1}){Button b=new Button(a);b.setText(n<0?"‹":"›");b.setTextColor(PremiumDesign40.WHITE);b.setTextSize(20);b.setBackgroundColor(Color.TRANSPARENT);b.setContentDescription(n<0?"Vorige slide":"Volgende slide");b.setOnClickListener(v->{if(!slides.isEmpty()){index=(index+n+slides.size())%slides.size();render();removeCallbacks(rotate);postDelayed(rotate,7000);}});if(n==1){dots=makeDots();controls.addView(dots,new LinearLayout.LayoutParams(0,dp(44),1));}controls.addView(b,new LinearLayout.LayoutParams(dp(48),dp(44)));}addView(controls,new LayoutParams(-1,dp(44),Gravity.BOTTOM));
  setOnClickListener(v->{if(slides.isEmpty())fallback.run();else open.open(slides.get(index));});render();
 }
 private TextView makeDots(){TextView v=PremiumDesign40.text(a,"",13,PremiumDesign40.GREEN,true);v.setGravity(Gravity.CENTER);v.setImportantForAccessibility(2);return v;}
 public void changed(JSONObject data,boolean loading,boolean failed){String selected=slides.isEmpty()?"":slides.get(index).optString("id");slides.clear();java.util.HashSet<String> ids=new java.util.HashSet<>();JSONArray rows=data==null?null:data.optJSONArray("articles");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r==null||!"published".equals(r.optString("status"))||r.optString("id").isEmpty()||!ids.add(r.optString("id")))continue;try{long age=System.currentTimeMillis()-java.time.Instant.parse(r.getString("publishedAt")).toEpochMilli();if(age>=0&&age<=7L*86400000&&!r.optString("headline").isEmpty())slides.add(r);}catch(Exception ignored){}}slides.sort((x,y)->y.optString("publishedAt").compareTo(x.optString("publishedAt")));while(slides.size()>5)slides.remove(slides.size()-1);index=0;for(int i=0;i<slides.size();i++)if(selected.equals(slides.get(i).optString("id")))index=i;render();}
 private void render(){if(slides.isEmpty()){image.setImageBitmap(PremiumDesign40.artwork(a,"news"));category.setText("VELDIO ORIGINALS");title.setText("Jouw voetbal.\nJouw verhalen.");intro.setText("Nog geen actuele publicaties. Open het nieuwsoverzicht.");dots.setText("");setContentDescription("Nieuws openen. Nog geen actuele publicaties.");return;}
  if(attached&&PremiumDesign40.motion(a)){image.setAlpha(.65f);image.animate().alpha(1f).setDuration(240).start();}
  JSONObject row=slides.get(index);category.setText(row.optString("category","Voetbal").toUpperCase(new Locale("nl","NL")));title.setText(row.optString("headline"));intro.setText(row.optString("standfirst","Lees het artikel"));Bitmap b=EditorialPhotos.bitmap(a,row,1000);if("column".equals(row.optString("type")))image.setImageDrawable(new EditorialArtwork(a,true));else if(b!=null)image.setImageBitmap(b);else image.setImageDrawable(new TopicArtwork39(row));StringBuilder d=new StringBuilder();for(int i=0;i<slides.size();i++)d.append(i==index?"● ":"○ ");dots.setText(d);setContentDescription(row.optString("headline")+", artikel openen, slide "+(index+1)+" van "+slides.size());
 }
 @Override public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()==0){downX=e.getX();downY=e.getY();}if(e.getActionMasked()==1&&Math.abs(e.getX()-downX)>dp(40)&&Math.abs(e.getX()-downX)>Math.abs(e.getY()-downY)*1.4){if(!slides.isEmpty()){index=(index+(e.getX()<downX?1:slides.size()-1))%slides.size();render();}return true;}return super.onTouchEvent(e);}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();attached=true;FeedRepository.subscribe(a,this);FeedRepository.refresh(false);postDelayed(rotate,7000);}
 @Override protected void onDetachedFromWindow(){attached=false;FeedRepository.unsubscribe(this);removeCallbacks(rotate);super.onDetachedFromWindow();}
}
